import org.junit.jupiter.api.Test;

class LmdbNativeInvocationSourceTest {

	@Test
	void canonicalBackingKeepsTheExactSyntheticInvocationSource() {
		NativeLmdbQuerySource dictionary = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(dictionary.hasCanonicalIds()).thenReturn(true);
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(dictionary);
		try (NativeExecutionContext owner = source.executionContext();
				LmdbFusedSipFactorizedRuntime.Session session = LmdbFusedSipFactorizedRuntime.create(1L, false)) {
			assertThat(source.hasCanonicalIds()).isFalse();
			LmdbNativeEvaluationStrategy bound = strategy().forInvocation(source, session, owner);
			assertThat(bound.nativeSource()).isSameAs(source);
			assertThat(bound.isBoundTo(source, session, owner)).isTrue();
			assertThat(bound.forSubplanInvocation(source, session, owner, null).nativeSource()).isSameAs(source);
		}
	}

	@Test
	void syntheticWrappersDoNotAdmitALegacyNoncanonicalDictionary() {
		NativeLmdbQuerySource dictionary = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(dictionary.hasCanonicalIds()).thenReturn(false);
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(dictionary);
		try (NativeExecutionContext owner = source.executionContext();
				LmdbFusedSipFactorizedRuntime.Session session = LmdbFusedSipFactorizedRuntime.create(2L, false)) {
			LmdbNativeEvaluationStrategy bound = strategy().forInvocation(source, session, owner);
			assertThat(bound.nativeSource()).isNull();
			assertThat(bound.forSubplanInvocation(source, session, owner, null).nativeSource()).isNull();
		}
	}

	@Test
	void scalarSubqueryWithoutNativeSourceDeclinesForGenericEvaluation() {
		var value = SimpleValueFactory.getInstance().createLiteral(1);
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", value);
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("value"));
		values.setBindingSets(List.of(row));
		CompareAny expression = new CompareAny(new ValueConstant(value), values, CompareOp.EQ);
		assertThat(NativeScalarSubqueryValueEvaluator.tryCompile(expression, strategy(),
				new QueryEvaluationContext.Minimal(null))).isNull();
	}

	private static LmdbNativeEvaluationStrategy strategy() {
		TripleSource triples = mock(TripleSource.class);
		when(triples.getValueFactory()).thenReturn(SimpleValueFactory.getInstance());
		return new LmdbNativeEvaluationStrategy(triples, null, null, 0L, new EvaluationStatistics(), false);
	}
}
